def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Recolor any full monochromatic row or column to the next color.
    rows = [r for r in range(h) if len(set(grid[r])) == 1]
    cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    for r in rows:
        old = grid[r][0]
        for c in range(w):
            out[r][c] = (old + 1) % 10
    for c in cols:
        old = grid[0][c]
        for r in range(h):
            out[r][c] = (old + 1) % 10
    return out
